# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">SABİT HIZLI HAREKET (DÜZGÜN DOĞRUSAL HAREKET — Δx = v · Δt)</text>\n  <rect x="20" y="45" width="660" height="105" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="350" y="66" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">EŞİT ZAMAN ARALIKLARINDA EŞİT YER DEĞİŞTİRME (v = +20 m/s SABİT)</text>\n  <line x1="60" y1="115" x2="640" y2="115" stroke="#1e3a8a" stroke-width="3"/>\n  <circle cx="90" cy="115" r="7" fill="#dc2626"/>\n  <text x="90" y="96" text-anchor="middle" font-size="11" font-weight="bold" fill="#b91c1c">t = 0 s</text>\n  <text x="90" y="138" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e3a8a">x₀ = 0 m</text>\n  <circle cx="250" cy="115" r="7" fill="#dc2626"/>\n  <text x="250" y="96" text-anchor="middle" font-size="11" font-weight="bold" fill="#b91c1c">t = 1 s</text>\n  <text x="250" y="138" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e3a8a">x₁ = +20 m</text>\n  <circle cx="410" cy="115" r="7" fill="#dc2626"/>\n  <text x="410" y="96" text-anchor="middle" font-size="11" font-weight="bold" fill="#b91c1c">t = 2 s</text>\n  <text x="410" y="138" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e3a8a">x₂ = +40 m</text>\n  <circle cx="570" cy="115" r="7" fill="#dc2626"/>\n  <text x="570" y="96" text-anchor="middle" font-size="11" font-weight="bold" fill="#b91c1c">t = 3 s</text>\n  <text x="570" y="138" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e3a8a">x₃ = +60 m</text>\n  <rect x="20" y="162" width="660" height="82" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="350" y="185" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">DÜZGÜN DOĞRUSAL HAREKETİN TEMEL ÖZELLİKLERİ</text>\n  <text x="40" y="208" font-size="11" font-weight="bold" fill="#14532d">• Yörünge doğrusal, hız vektörünün yönü ve büyüklüğü sabittir (v = sabit, ivme a = 0).</text>\n  <text x="40" y="228" font-size="11" font-weight="bold" fill="#14532d">• Konum denklemi: x(t) = x₀ + v · t  |  Yer değiştirme: Δx = x - x₀ = v · Δt</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">KONUM-ZAMAN (x-t) VE HIZ-ZAMAN (v-t) GRAFİKLERİNİN ANALİZİ</text>\n  <rect x="20" y="45" width="320" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">KONUM - ZAMAN (x - t) GRAFİĞİ</text>\n  <line x1="65" y1="185" x2="65" y2="80" stroke="#0f172a" stroke-width="2"/>\n  <line x1="65" y1="185" x2="295" y2="185" stroke="#0f172a" stroke-width="2"/>\n  <line x1="65" y1="185" x2="255" y2="95" stroke="#dc2626" stroke-width="3"/>\n  <line x1="255" y1="95" x2="255" y2="185" stroke="#64748b" stroke-width="1.5" stroke-dasharray="4,3"/>\n  <line x1="65" y1="95" x2="255" y2="95" stroke="#64748b" stroke-width="1.5" stroke-dasharray="4,3"/>\n  <text x="50" y="99" text-anchor="end" font-size="10.5" font-weight="bold" fill="#dc2626">x</text>\n  <text x="255" y="200" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#dc2626">t</text>\n  <text x="180" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e3a8a">EĞİM = Δx / Δt = HIZ (v)</text>\n  <rect x="360" y="45" width="320" height="195" rx="10" fill="#fffbeb" stroke="#d97706" stroke-width="2"/>\n  <text x="520" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#b45309">HIZ - ZAMAN (v - t) GRAFİĞİ</text>\n  <line x1="405" y1="185" x2="405" y2="80" stroke="#0f172a" stroke-width="2"/>\n  <line x1="405" y1="185" x2="635" y2="185" stroke="#0f172a" stroke-width="2"/>\n  <rect x="405" y="110" width="190" height="75" fill="#fde68a" opacity="0.7"/>\n  <line x1="405" y1="110" x2="595" y2="110" stroke="#16a34a" stroke-width="3"/>\n  <line x1="595" y1="110" x2="595" y2="185" stroke="#64748b" stroke-width="1.5" stroke-dasharray="4,3"/>\n  <text x="392" y="114" text-anchor="end" font-size="10.5" font-weight="bold" fill="#16a34a">v</text>\n  <text x="595" y="200" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#16a34a">t</text>\n  <text x="500" y="152" text-anchor="middle" font-size="11" font-weight="bold" fill="#78350f">ALAN = Δx = v · t</text>\n  <text x="520" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#b45309">ALTINDAKİ ALAN = YER DEĞİŞTİRME (Δx)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">İVMELİ HAREKET VE SABİT İVMELİ HAREKETTE HIZ DEĞİŞİMİ</text>\n  <rect x="20" y="45" width="320" height="195" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#7e22ce">İVME KAVRAMI (a = Δv / Δt)</text>\n  <text x="35" y="96" font-size="11" font-weight="bold" fill="#581c87">• Birim zamandaki hız değişimidir.</text>\n  <text x="35" y="120" font-size="11" font-weight="bold" fill="#581c87">• Vektörel büyüklüktür; SI birimi m/s²\'dir.</text>\n  <text x="35" y="144" font-size="11" font-weight="bold" fill="#581c87">• Formül: a = (v_son - v_ilk) / Δt</text>\n  <text x="35" y="170" font-size="10.5" font-weight="bold" fill="#15803d">• v - t grafiğinin EĞİMİ ivmeyi (a) verir.</text>\n  <text x="35" y="194" font-size="10.5" font-weight="bold" fill="#b91c1c">• a - t grafiğinin ALANI hız değişimini (Δv) verir.</text>\n  <text x="35" y="218" font-size="10.5" fill="#581c87">• Sabit hızlı harekette Δv = 0 → a = 0 m/s².</text>\n  <rect x="360" y="45" width="320" height="195" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#b91c1c">HIZLANMA VE YAVAŞLAMA KOŞULU</text>\n  <text x="378" y="98" font-size="11" font-weight="bold" fill="#15803d">1. Hızlanan Hareket:</text>\n  <text x="378" y="116" font-size="10.5" fill="#166534">Hız vektörü (v) ile ivme vektörü (a) AYNI yönlüdür</text>\n  <text x="378" y="132" font-size="10.5" font-weight="bold" fill="#15803d">(+v ve +a  veya  -v ve -a).</text>\n  <text x="378" y="162" font-size="11" font-weight="bold" fill="#dc2626">2. Yavaşlayan Hareket:</text>\n  <text x="378" y="180" font-size="10.5" fill="#991b1b">Hız vektörü (v) ile ivme vektörü (a) ZIT yönlüdür</text>\n  <text x="378" y="196" font-size="10.5" font-weight="bold" fill="#dc2626">(+v ve -a  veya  -v ve +a).</text>\n  <text x="378" y="220" font-size="10.5" font-weight="bold" fill="#0f172a">Serbest düşme ivmesi: g ≈ 9,8 m/s² (veya 10 m/s²)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
